{
  "tests": [
    {
      "id": "ca-et-factures-mois",
      "titre": "Tableau de bord : CA du mois et nombre de factures du mois",
      "setup": "Connecté avec le compte de démo, sur le tableau de bord, sans filtre.",
      "etapes": [
        "Cliquer sur le menu « Factures »."
      ],
      "resultat_attendu": "Le CA du mois et le nombre de factures du mois sont cohérents avec les totaux de la liste des factures.",
      "verifications": [
        "FAIL if le CA du mois affiché n’est pas égal au total affiché en bas du tableau de la liste des factures.",
        "FAIL if le nombre de factures du mois affiché n’est pas égal au nombre de factures indiqué sous le tableau."
      ],
      "releves": [
        {
          "ecran": "tableau-de-bord",
          "vue": "defaut"
        },
        {
          "ecran": "liste-des-factures",
          "vue": "defaut"
        }
      ],
      "regles_calculables": [
        {
          "type": "egalite",
          "a": {
            "ecran": "tableau-de-bord",
            "champ": "CA du mois"
          },
          "b": {
            "ecran": "liste-des-factures",
            "champ": "Total"
          }
        },
        {
          "type": "egalite",
          "a": {
            "ecran": "tableau-de-bord",
            "champ": "Factures du mois"
          },
          "b": {
            "ecran": "liste-des-factures",
            "champ": "Nombre de factures"
          }
        }
      ],
      "passages_de_la_source": [
        "- Le « CA du mois » du [[tableau-de-bord]] est égal au total de la [[liste-des-factures]].",
        "- Le nombre de « Factures du mois » du [[tableau-de-bord]] est égal au nombre de factures de la [[liste-des-factures]]."
      ],
      "questions": []
    },
    {
      "id": "total-ttc-detail",
      "titre": "Detail facture : Total TTC",
      "setup": "Connecté avec le compte de démo, sur la liste des factures, sans filtre.",
      "etapes": [
        "Cliquer sur le numéro de la facture « F-119 »."
      ],
      "resultat_attendu": "Le Total TTC affiché dans le détail correspond au montant TTC indiqué dans la liste des factures.",
      "verifications": [
        "FAIL if le Total TTC du détail n’est pas égal au Montant TTC de la facture F-119 dans la liste."
      ],
      "releves": [
        {
          "ecran": "liste-des-factures",
          "vue": "defaut"
        },
        {
          "ecran": "detail-facture",
          "vue": "defaut"
        }
      ],
      "regles_calculables": [
        {
          "type": "egalite",
          "a": {
            "ecran": "detail-facture",
            "champ": "Total TTC"
          },
          "b": {
            "ecran": "liste-des-factures",
            "champ": "Montant TTC de F-119"
          }
        }
      ],
      "passages_de_la_source": [
        "- Le « Total TTC » du [[detail-facture]] est égal au montant de la même facture dans la [[liste-des-factures]]. Facture témoin : F-119."
      ],
      "questions": []
    }
  ]
}

